NS = int(re.search(r'THE SIFREI ROWS TYPED \(chapters 19-21\): (\d+)', cb).group(1)); NO = int(re.search(r'Onkelos typed: (\d+)', cb).group(1)); NOUT = int(re.search(r'outside typed: (\d+)', cb).group(1)); FAILS = re.search(r"the cuts' misses \(FAIL\): (\[.*\])", cb).group(1)
